"""Validate exact reviewed hunks and report immutable scope; no repo writes."""
import ast
import hashlib
import importlib.metadata
import json
from pathlib import Path
import platform
import re

REPO = Path('[REPO]')
PAYLOAD = Path('[SCRATCH]/split-immediate-round2-lvpkgtyc/review-payload-r2.diff')


def digest(data):
    return hashlib.sha256(data).hexdigest()


def reverse_payload():
    lines = PAYLOAD.read_text().splitlines(keepends=True)
    hunks = {}
    active = None
    index = 0
    while index < len(lines):
        line = lines[index]
        if line.startswith('+++ '):
            active = line[4:].strip().split('/', 1)[1]
            hunks[active] = []
            index += 1
            continue
        match = re.match(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', line)
        if not match:
            index += 1
            continue
        old_at, old_count, new_at, new_count = [int(x) if x is not None else 1 for x in match.groups()]
        index += 1
        old, new = [], []
        while index < len(lines) and not lines[index].startswith(('@@ ', '--- ')):
            entry = lines[index]
            if not entry.startswith((' ', '+', '-')):
                break
            if entry[0] in ' -':
                old.append(entry[1:])
            if entry[0] in ' +':
                new.append(entry[1:])
            index += 1
        if len(old) != old_count or len(new) != new_count:
            raise ValueError('Hunk line count mismatch')
        hunks[active].append((old_at, new_at, old, new))
    if set(hunks) != {'patch.py', 'tests/test_patch_x86_immediates.py'}:
        raise ValueError('Unexpected delta file membership')
    results = {}
    for relative, file_hunks in hunks.items():
        current = (REPO / relative).read_text().splitlines(keepends=True)
        baseline = list(current)
        for old_at, new_at, old, new in reversed(file_hunks):
            if baseline[new_at - 1:new_at - 1 + len(new)] != new:
                raise ValueError('Current source does not match new hunk: ' + relative)
            baseline[new_at - 1:new_at - 1 + len(new)] = old
        replay = list(baseline)
        for old_at, new_at, old, new in reversed(file_hunks):
            if replay[old_at - 1:old_at - 1 + len(old)] != old:
                raise ValueError('Reconstructed baseline does not match old hunk: ' + relative)
            replay[old_at - 1:old_at - 1 + len(old)] = new
        if replay != current:
            raise ValueError('Delta replay did not reproduce current source')
        before, after = ''.join(baseline), ''.join(current)
        results[relative] = {'hunks': len(file_hunks), 'reverse_and_replay_exact': True,
                             'baseline_sha256': digest(before.encode()),
                             'current_sha256': digest(after.encode())}
        if relative == 'patch.py':
            def funcs(text):
                return {node.name: ast.dump(node, include_attributes=False)
                        for node in ast.parse(text).body if isinstance(node, ast.FunctionDef)}
            before_funcs, after_funcs = funcs(before), funcs(after)
            changed = sorted(name for name in set(before_funcs) | set(after_funcs)
                             if before_funcs.get(name) != after_funcs.get(name))
            results[relative]['changed_top_level_functions'] = changed
            results[relative]['unchanged_other_functions'] = sorted(set(after_funcs) - set(changed))
            before_suffix = before[before.index('def _replace_keys('):]
            after_suffix = after[after.index('def _replace_keys('):]
            results[relative]['replace_keys_and_all_following_bytes_unchanged'] = before_suffix == after_suffix
            if changed != ['_x86_immediate_matches'] or before_suffix != after_suffix:
                raise ValueError('Unexpected code scope drift')
    return results


if __name__ == '__main__':
    import capstone
    print(json.dumps({'delta': reverse_payload(), 'environment': {
        'python': platform.python_version(),
        'capstone_distribution': importlib.metadata.version('capstone'),
        'capstone_runtime': capstone.__version__,
        'capstone_native': list(capstone.cs_version()),
        'note': 'Distribution/runtime version mismatch is a recorded baseline, not a round-2 defect.'
    }}, indent=2))
